import{_ as r,o,c as e,a2 as s}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"문제 해결","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/troubleshooting.md","filePath":"ko-KR/user-guide/troubleshooting.md","lastUpdated":1787586465000}'),a={name:"ko-KR/user-guide/troubleshooting.md"};function n(i,t,l,g,h,d){return o(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="문제-해결" tabindex="-1">문제 해결 <a class="header-anchor" href="#문제-해결" aria-label="Permalink to &quot;문제 해결&quot;">​</a></h1><p>Lertaro 사용 중 문제가 발생했나요? 아래 단계에 따라 일반적인 원인을 확인하고 해결하세요.</p><h2 id="_1-전역-단축키가-작동하지-않음" tabindex="-1">1. 전역 단축키가 작동하지 않음 <a class="header-anchor" href="#_1-전역-단축키가-작동하지-않음" aria-label="Permalink to &quot;1. 전역 단축키가 작동하지 않음&quot;">​</a></h2><ul><li><strong>백그라운드 서비스 실행 여부 확인</strong>: <a href="./settings/service-status.html"><strong>설정 → 서비스 상태</strong></a>로 이동하여 <code>Lertaro.Service</code>가 실행 중인지 확인하세요. 일반 단축키는 App이 처리하지만 관리자 권한 후킹 프로세스는 서비스에 의존합니다.</li><li><strong>관리자 권한 격리 (UIPI)</strong>: 현재 활성 창이 관리자 권한으로 실행된 경우(예: 관리자 터미널, 작업 관리자) Windows UIPI 보안 정책으로 인해 일반 프로세스의 단축키 입력이 차단됩니다. Lertaro는 서비스를 통해 후킹을 자동 승격하므로 서비스가 정상 동작 중인지 확인하세요.</li><li><strong>프로세스 블랙리스트 확인</strong>: <a href="./settings/hotkeys-page.html#프로세스-블랙리스트"><strong>설정 → 단축키</strong></a>에서 현재 프로그램이 블랙리스트에 등록되어 있지 않은지 확인하세요. 블랙리스트에 포함된 앱이 활성화되어 있으면 Lertaro는 단축키를 가로채지 않습니다.</li><li><strong>전체화면 게임/앱 자동 무시</strong>: 전체화면 3D 게임이나 비디오 재생기가 실행 중일 때는 단축키가 기본적으로 무시됩니다. 전체화면에서도 검색창을 띄우려면 <strong>설정 → 단축키</strong>에서 <strong>전체화면 앱 포커스 시에도 응답</strong>을 켜세요.</li></ul><h2 id="_2-검색-결과가-갱신되지-않거나-오래됨" tabindex="-1">2. 검색 결과가 갱신되지 않거나 오래됨 <a class="header-anchor" href="#_2-검색-결과가-갱신되지-않거나-오래됨" aria-label="Permalink to &quot;2. 검색 결과가 갱신되지 않거나 오래됨&quot;">​</a></h2><ul><li><strong>로컬 NTFS / ReFS 드라이브</strong>: USN 변경 저널을 읽어 거의 지연 없는 밀리초 단위로 실시간 갱신됩니다.</li><li><strong>FAT32 / exFAT 드라이브</strong>: 파일 시스템 변경 이벤트를 통해 지속적으로 감지합니다.</li><li><strong>수동 인덱스 재구축</strong>: 예기치 않은 전원 차단 등으로 인덱스 불일치가 발생한 경우, <a href="./settings/index-drives.html"><strong>설정 → 인덱싱 → 로컬 드라이브</strong></a>에서 해당 드라이브의 <strong>인덱스 재구축</strong>을 클릭하세요.</li></ul><h2 id="_3-네트워크-드라이브가-자동-갱신되지-않음" tabindex="-1">3. 네트워크 드라이브가 자동 갱신되지 않음 <a class="header-anchor" href="#_3-네트워크-드라이브가-자동-갱신되지-않음" aria-label="Permalink to &quot;3. 네트워크 드라이브가 자동 갱신되지 않음&quot;">​</a></h2><ul><li><strong>정기 스캔 메커니즘</strong>: 네트워크 공유(SMB / NAS)는 로컬 USN 저널이 없으므로 정기적인 폴링 스캔에 의존합니다.</li><li><strong>새로고침 모드 확인</strong>: <a href="./settings/index-drives.html#네트워크-드라이브"><strong>설정 → 인덱싱 → 네트워크 드라이브</strong></a>에서 해당 드라이브의 새로고침 모드가 &quot;수동&quot;으로 되어 있지 않은지 확인하세요.</li><li><strong>심볼릭 링크 순환 보호</strong>: NAS 상의 재귀적 심볼릭 링크로 인한 무한 루프를 방지하기 위해 순환 감지 엔진이 자동으로 중복 경로를 건너뜁니다.</li></ul><h2 id="_4-특정-파일이나-폴더가-검색되지-않음" tabindex="-1">4. 특정 파일이나 폴더가 검색되지 않음 <a class="header-anchor" href="#_4-특정-파일이나-폴더가-검색되지-않음" aria-label="Permalink to &quot;4. 특정 파일이나 폴더가 검색되지 않음&quot;">​</a></h2><ul><li><strong>제외 규칙 확인</strong>: <a href="./settings/index-drives.html#제외-규칙"><strong>설정 → 인덱싱 → 제외 규칙</strong></a>에서 해당 파일 경로가 정확한 경로, 와일드카드, 정규식에 의해 실수로 제외되지 않았는지 확인하세요.</li><li><strong>드라이브 활성화 상태 확인</strong>: <a href="./settings/index-drives.html"><strong>설정 → 인덱싱 → 로컬 드라이브</strong></a>에서 해당 드라이브가 활성화되어 있는지 확인하세요.</li></ul><h2 id="_5-인라인-윈도우에서-ime-한글-후보-창이-뜨지-않음" tabindex="-1">5. 인라인 윈도우에서 IME 한글 후보 창이 뜨지 않음 <a class="header-anchor" href="#_5-인라인-윈도우에서-ime-한글-후보-창이-뜨지-않음" aria-label="Permalink to &quot;5. 인라인 윈도우에서 IME 한글 후보 창이 뜨지 않음&quot;">​</a></h2><ul><li><strong>포커스 비점유 설계</strong>: <a href="./getting-started.html#3-세-가지-윈도우-모드">인라인 윈도우</a>는 닫힌 후 원래 프로그램으로 포커스를 깜빡임 없이 돌려주기 위해 포커스를 가로채지 않는 구조입니다. 한글 IME 후보 창은 Windows 정식 포커스를 요구하므로 인라인 모드에서는 나타나지 않을 수 있습니다.</li><li><strong>권장 해결 방법</strong>: <ol><li><strong>퀵 윈도우 사용</strong>: <code>Ctrl</code> 더블 클릭으로 열리는 퀵 윈도우는 정식 포커스를 가지므로 모든 IME가 정상 작동합니다.</li></ol></li></ul><h2 id="_6-로그-확인-및-이슈-등록" tabindex="-1">6. 로그 확인 및 이슈 등록 <a class="header-anchor" href="#_6-로그-확인-및-이슈-등록" aria-label="Permalink to &quot;6. 로그 확인 및 이슈 등록&quot;">​</a></h2><p>문제가 지속되면 <a href="./settings/service-status.html"><strong>설정 → 서비스 상태</strong></a>에서 실시간 로그를 확인하세요.</p><ul><li><strong>Service 로그</strong>: 인덱싱, USN 저널, 네트워크 스캔, IPC 통신 기록.</li><li><strong>App 로그</strong>: UI 렌더링, 플러그인 로드, 단축키 및 설정 변경 기록.</li><li><strong>Hook 로그</strong>: 전역 키보드 후크 및 마우스 제스처 이벤트 스트림.</li></ul><p>검색창으로 키워드를 필터링하거나 심각도(Info / Warn / Error)로 정렬하여 에러를 확인하고 GitHub Issue 등록 시 첨부해 주세요.</p>',16)])])}const _=r(a,[["render",n]]);export{c as __pageData,_ as default};
